class ManagedConnection:
    def __init__(self, name, log):
        self.name = name
        self.log = log

    def __enter__(self):
        self.log.append(f'{self.name}:open')
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.log.append(f'{self.name}:closed')
        return False
